export const SETUP_SQL: { file: string; sql: string }[] = [
  { file: "supabase/migrations/0001_schema.sql", sql: "-- SocialGrid V1 schema\n-- Tables, enums and helper functions. RLS lives in 0002, storage in 0003.\n\ncreate extension if not exists pgcrypto;\n\n-- ---------------------------------------------------------------------------\n-- Enums (add values later with `alter type ... add value`)\n-- ---------------------------------------------------------------------------\ncreate type public.industry as enum ('salon', 'restaurant', 'cafe', 'cloud_kitchen');\ncreate type public.autonomy_mode as enum ('manual', 'ai_draft_review', 'auto');\ncreate type public.content_type as enum (\n  'single_post', 'carousel', 'story', 'reel', 'festival_greeting', 'caption_only'\n);\ncreate type public.message_sender as enum ('client', 'expert', 'system');\ncreate type public.message_kind as enum (\n  'text', 'voice', 'images', 'options_card', 'suggestion', 'status'\n);\ncreate type public.request_source as enum ('chat', 'quick_start', 'suggestion', 'plan_slot');\ncreate type public.request_status as enum (\n  'new', 'in_progress', 'delivered', 'revision_requested', 'completed', 'cancelled'\n);\ncreate type public.rule_scope as enum ('client', 'industry', 'global');\ncreate type public.example_source as enum ('delivered', 'manual');\ncreate type public.suggestion_kind as enum ('festival', 'inactivity', 'plan_reminder', 'custom');\ncreate type public.suggestion_status as enum ('pending', 'accepted', 'dismissed');\ncreate type public.subscription_status as enum ('trial', 'active', 'past_due', 'paused', 'expired');\ncreate type public.plan_slot_status as enum ('planned', 'waiting_photo', 'in_progress', 'done');\ncreate type public.emoji_level as enum ('none', 'some', 'lots');\n\n-- ---------------------------------------------------------------------------\n-- Roles & profiles\n-- ---------------------------------------------------------------------------\ncreate table public.roles (\n  id   smallint primary key,\n  name text not null unique\n);\ninsert into public.roles (id, name) values (1, 'expert'), (2, 'client');\n\ncreate table public.profiles (\n  id                    uuid primary key references auth.users (id) on delete cascade,\n  role_id               smallint not null references public.roles (id),\n  display_name          text not null,\n  phone                 text unique,\n  preferred_ui_language text not null default 'en' check (preferred_ui_language in ('en', 'hi')),\n  created_at            timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Businesses & brand\n-- ---------------------------------------------------------------------------\ncreate table public.businesses (\n  id                  uuid primary key default gen_random_uuid(),\n  owner_profile_id    uuid not null unique references public.profiles (id) on delete restrict,\n  name                text not null,\n  industry            public.industry not null,\n  autonomy_mode       public.autonomy_mode not null default 'manual',\n  suggestions_enabled boolean not null default true,\n  photo_consent       boolean not null default false,\n  created_at          timestamptz not null default now()\n);\n\ncreate table public.brand_profiles (\n  business_id       uuid primary key references public.businesses (id) on delete cascade,\n  owner_name        text,\n  address           text,\n  maps_link         text,\n  timings           text,\n  contact_phone     text,\n  whatsapp          text,\n  logo_path         text,\n  colors            jsonb not null default '{\"primary\":\"#E8590C\",\"secondary\":\"#FFF4E6\",\"accent\":\"#2B8A3E\"}',\n  font_style        text not null default 'modern',\n  example_paths     jsonb not null default '[]',\n  tone              text not null default 'friendly',\n  content_languages text[] not null default '{en}',\n  default_language  text not null default 'en',\n  emoji_level       public.emoji_level not null default 'some',\n  audience          text,\n  audience_tags     text[] not null default '{}',\n  avoid_list        text[] not null default '{}',\n  avoid_custom      text,\n  signature_items   text,\n  current_offers    text,\n  updated_at        timestamptz not null default now()\n);\n\ncreate table public.offerings (\n  id           uuid primary key default gen_random_uuid(),\n  business_id  uuid not null references public.businesses (id) on delete cascade,\n  name         text not null,\n  price        numeric(10, 2),\n  description  text,\n  photo_path   text,\n  is_signature boolean not null default false,\n  sort         int not null default 0,\n  created_at   timestamptz not null default now()\n);\ncreate index on public.offerings (business_id);\n\n-- Photos the client adds from the \"Your brand\" page\ncreate table public.brand_photos (\n  id          uuid primary key default gen_random_uuid(),\n  business_id uuid not null references public.businesses (id) on delete cascade,\n  path        text not null,\n  uploaded_by uuid references public.profiles (id),\n  created_at  timestamptz not null default now()\n);\ncreate index on public.brand_photos (business_id);\n\n-- ---------------------------------------------------------------------------\n-- Weekly plan\n-- ---------------------------------------------------------------------------\ncreate table public.weekly_plans (\n  business_id uuid primary key references public.businesses (id) on delete cascade,\n  -- [{ \"type\": \"reel\", \"goal\": \"offer\", \"day\": 1 }]  day: 0 = Monday ... 6 = Sunday\n  slots       jsonb not null default '[]',\n  updated_at  timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Conversations & requests\n-- ---------------------------------------------------------------------------\ncreate table public.conversations (\n  id          uuid primary key default gen_random_uuid(),\n  business_id uuid not null unique references public.businesses (id) on delete cascade,\n  created_at  timestamptz not null default now()\n);\n\ncreate table public.requests (\n  id                 uuid primary key default gen_random_uuid(),\n  business_id        uuid not null references public.businesses (id) on delete cascade,\n  source             public.request_source not null default 'chat',\n  quick_start_type   text,\n  structured_answers jsonb not null default '{}',\n  summary            text,\n  content_type       public.content_type,\n  language           text,\n  is_urgent          boolean not null default false,\n  status             public.request_status not null default 'new',\n  due_at             timestamptz not null,\n  current_revision   int not null default 0,\n  plan_slot_id       uuid,\n  suggestion_id      uuid,\n  created_by         uuid references public.profiles (id),\n  created_at         timestamptz not null default now(),\n  updated_at         timestamptz not null default now(),\n  delivered_at       timestamptz,\n  completed_at       timestamptz\n);\ncreate index on public.requests (business_id, created_at desc);\ncreate index on public.requests (status, due_at);\n\ncreate table public.plan_slots (\n  id          uuid primary key default gen_random_uuid(),\n  business_id uuid not null references public.businesses (id) on delete cascade,\n  week_start  date not null,\n  slot_index  int not null,\n  day         smallint not null default 0,\n  type        public.content_type not null,\n  goal        text,\n  status      public.plan_slot_status not null default 'planned',\n  request_id  uuid references public.requests (id) on delete set null,\n  reminded_at timestamptz,\n  unique (business_id, week_start, slot_index)\n);\nalter table public.requests\n  add constraint requests_plan_slot_fk foreign key (plan_slot_id)\n  references public.plan_slots (id) on delete set null;\n\ncreate table public.messages (\n  id                uuid primary key default gen_random_uuid(),\n  conversation_id   uuid not null references public.conversations (id) on delete cascade,\n  sender            public.message_sender not null,\n  sender_profile_id uuid references public.profiles (id),\n  kind              public.message_kind not null default 'text',\n  body              text,\n  -- [{ \"bucket\": \"client-uploads\", \"path\": \"...\", \"type\": \"image\" | \"audio\", \"duration\": 12 }]\n  attachments       jsonb not null default '[]',\n  -- kind-specific data: chips, option ids, suggestion id, i18n key + params for system text\n  payload           jsonb not null default '{}',\n  request_id        uuid references public.requests (id) on delete set null,\n  created_at        timestamptz not null default now()\n);\ncreate index on public.messages (conversation_id, created_at);\ncreate index on public.messages (request_id);\n\ncreate table public.conversation_reads (\n  conversation_id uuid not null references public.conversations (id) on delete cascade,\n  profile_id      uuid not null references public.profiles (id) on delete cascade,\n  last_read_at    timestamptz not null default now(),\n  primary key (conversation_id, profile_id)\n);\n\ncreate table public.revisions (\n  id                 uuid primary key default gen_random_uuid(),\n  request_id         uuid not null references public.requests (id) on delete cascade,\n  number             int not null,\n  client_feedback    text,\n  feedback_chip      text,\n  expert_change_note text,\n  due_at             timestamptz,\n  created_at         timestamptz not null default now(),\n  unique (request_id, number)\n);\n\ncreate table public.content_options (\n  id               uuid primary key default gen_random_uuid(),\n  request_id       uuid not null references public.requests (id) on delete cascade,\n  revision_id      uuid references public.revisions (id) on delete set null,\n  revision_number  int not null default 0,\n  position         int not null default 0,\n  content_type     public.content_type not null default 'single_post',\n  -- [{ \"path\": \"...\", \"type\": \"image\" | \"video\", \"name\": \"slide-1.jpg\" }]\n  media            jsonb not null default '[]',\n  caption          text,\n  hashtags         text,\n  language         text not null default 'en',\n  -- { \"script\": \"\", \"shot_list\": \"\", \"on_screen_text\": \"\", \"audio_mood\": \"\" }\n  reel_fields      jsonb not null default '{}',\n  -- { \"occasion\": [], \"style\": [], \"goal\": [] }\n  tags             jsonb not null default '{}',\n  why_it_works     text,\n  expert_notes     text,\n  chosen           boolean not null default false,\n  is_gold_standard boolean not null default false,\n  brand_snapshot   jsonb,\n  created_by       uuid references public.profiles (id),\n  created_at       timestamptz not null default now(),\n  delivered_at     timestamptz\n);\ncreate index on public.content_options (request_id);\n\ncreate table public.downloads (\n  id         uuid primary key default gen_random_uuid(),\n  option_id  uuid not null references public.content_options (id) on delete cascade,\n  profile_id uuid not null references public.profiles (id) on delete cascade,\n  action     text not null default 'download',\n  created_at timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Teaching library\n-- ---------------------------------------------------------------------------\ncreate table public.rules (\n  id          uuid primary key default gen_random_uuid(),\n  scope       public.rule_scope not null default 'client',\n  business_id uuid references public.businesses (id) on delete cascade,\n  industry    public.industry,\n  text        text not null,\n  active      boolean not null default true,\n  created_by  uuid references public.profiles (id),\n  created_at  timestamptz not null default now(),\n  check (\n    (scope = 'client' and business_id is not null)\n    or (scope = 'industry' and industry is not null)\n    or scope = 'global'\n  )\n);\n\ncreate table public.examples (\n  id               uuid primary key default gen_random_uuid(),\n  source           public.example_source not null,\n  option_id        uuid unique references public.content_options (id) on delete cascade,\n  request_id       uuid references public.requests (id) on delete set null,\n  industry         public.industry,\n  business_id      uuid references public.businesses (id) on delete set null,\n  content_type     public.content_type,\n  media            jsonb not null default '[]',\n  caption          text,\n  notes            text,\n  tags             jsonb not null default '{}',\n  is_gold_standard boolean not null default false,\n  brand_snapshot   jsonb,\n  created_by       uuid references public.profiles (id),\n  created_at       timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Calendar & suggestions\n-- ---------------------------------------------------------------------------\ncreate table public.festivals (\n  id                uuid primary key default gen_random_uuid(),\n  name              text not null,\n  name_hi           text not null,\n  date              date not null,\n  industries        public.industry[] not null default '{salon,restaurant,cafe,cloud_kitchen}',\n  default_lead_days int not null default 5,\n  active            boolean not null default true\n);\ncreate index on public.festivals (date);\n\ncreate table public.suggestions (\n  id          uuid primary key default gen_random_uuid(),\n  business_id uuid not null references public.businesses (id) on delete cascade,\n  kind        public.suggestion_kind not null,\n  -- { \"title_en\", \"title_hi\", \"text_en\", \"text_hi\", \"festival_id\", \"content_type\" }\n  payload     jsonb not null default '{}',\n  dedupe_key  text,\n  show_at     timestamptz not null default now(),\n  status      public.suggestion_status not null default 'pending',\n  message_id  uuid references public.messages (id) on delete set null,\n  created_by  uuid references public.profiles (id),\n  created_at  timestamptz not null default now(),\n  unique (business_id, dedupe_key)\n);\n\n-- ---------------------------------------------------------------------------\n-- Plans & subscriptions\n-- ---------------------------------------------------------------------------\ncreate table public.plans (\n  id        uuid primary key default gen_random_uuid(),\n  name      text not null,\n  price_inr int not null default 0,\n  -- { \"requests_per_month\": null | number, \"content_types\": null | [\"single_post\", ...] }\n  limits    jsonb not null default '{}',\n  active    boolean not null default true\n);\n\ncreate table public.subscriptions (\n  id                 uuid primary key default gen_random_uuid(),\n  business_id        uuid not null unique references public.businesses (id) on delete cascade,\n  plan_id            uuid references public.plans (id),\n  status             public.subscription_status not null default 'trial',\n  current_period_end timestamptz,\n  provider           text not null default 'manual',\n  provider_ref       text,\n  updated_at         timestamptz not null default now()\n);\n\n-- ---------------------------------------------------------------------------\n-- Settings (single row) & quick-start cards\n-- ---------------------------------------------------------------------------\ncreate table public.settings (\n  id                   smallint primary key default 1 check (id = 1),\n  standard_hours       numeric(5, 2) not null default 6,\n  urgent_hours         numeric(5, 2) not null default 2,\n  revision_hours       numeric(5, 2) not null default 3,\n  work_start           time not null default '09:00',\n  work_end             time not null default '21:00',\n  -- ISO weekday numbers: 1 = Monday ... 7 = Sunday\n  work_days            smallint[] not null default '{1,2,3,4,5,6,7}',\n  timezone             text not null default 'Asia/Kolkata',\n  suggestion_lead_days int not null default 5,\n  inactivity_days      int not null default 7,\n  updated_at           timestamptz not null default now()\n);\ninsert into public.settings (id) values (1);\n\ncreate table public.quick_start_cards (\n  id           uuid primary key default gen_random_uuid(),\n  industry     public.industry not null,\n  key          text not null,\n  label_en     text not null,\n  label_hi     text not null,\n  icon         text not null default 'sparkles',\n  content_type public.content_type not null default 'single_post',\n  -- [{ \"id\": \"item\", \"q_en\": \"\", \"q_hi\": \"\", \"type\": \"choice\" | \"text\" | \"photo\",\n  --    \"options\": [{ \"en\": \"\", \"hi\": \"\" }] }]\n  questions    jsonb not null default '[]',\n  sort         int not null default 0,\n  active       boolean not null default true,\n  unique (industry, key)\n);\n\n-- ---------------------------------------------------------------------------\n-- Helper functions (security definer so they can be used inside RLS policies)\n-- ---------------------------------------------------------------------------\ncreate or replace function public.is_expert()\nreturns boolean\nlanguage sql stable security definer set search_path = public\nas $$\n  select exists (\n    select 1 from profiles p join roles r on r.id = p.role_id\n    where p.id = auth.uid() and r.name = 'expert'\n  );\n$$;\n\ncreate or replace function public.owns_business(bid uuid)\nreturns boolean\nlanguage sql stable security definer set search_path = public\nas $$\n  select exists (select 1 from businesses b where b.id = bid and b.owner_profile_id = auth.uid());\n$$;\n\n-- Same check for storage paths, whose first folder is the business id as text\ncreate or replace function public.owns_business_folder(folder text)\nreturns boolean\nlanguage sql stable security definer set search_path = public\nas $$\n  select exists (\n    select 1 from businesses b where b.id::text = folder and b.owner_profile_id = auth.uid()\n  );\n$$;\n\ncreate or replace function public.can_see_business(bid uuid)\nreturns boolean\nlanguage sql stable security definer set search_path = public\nas $$\n  select public.is_expert() or public.owns_business(bid);\n$$;\n\n-- The single place where \"may this business create a new request?\" is decided.\n-- Returns 'ok', 'inactive' (paused/expired), 'limit_reached' or 'type_not_allowed'.\ncreate or replace function public.request_access(bid uuid, ctype public.content_type default null)\nreturns text\nlanguage plpgsql stable security definer set search_path = public\nas $$\ndeclare\n  sub    subscriptions%rowtype;\n  lim    jsonb;\n  quota  int;\n  used   int;\n  tz     text;\nbegin\n  select * into sub from subscriptions where business_id = bid;\n  if found and sub.status in ('paused', 'expired') then\n    return 'inactive';\n  end if;\n\n  if found and sub.plan_id is not null then\n    select limits into lim from plans where id = sub.plan_id;\n  end if;\n  lim := coalesce(lim, '{}'::jsonb);\n\n  if ctype is not null and jsonb_typeof(lim -> 'content_types') = 'array'\n     and not (lim -> 'content_types') ? ctype::text then\n    return 'type_not_allowed';\n  end if;\n\n  if jsonb_typeof(lim -> 'requests_per_month') = 'number' then\n    quota := (lim ->> 'requests_per_month')::int;\n    select timezone into tz from settings where id = 1;\n    select count(*) into used from requests r\n    where r.business_id = bid\n      and r.status <> 'cancelled'\n      and r.created_at >= (date_trunc('month', now() at time zone coalesce(tz, 'Asia/Kolkata'))\n                           at time zone coalesce(tz, 'Asia/Kolkata'));\n    if used >= quota then\n      return 'limit_reached';\n    end if;\n  end if;\n\n  return 'ok';\nend;\n$$;\n\n-- Client may edit only timings and offering prices; everything else is expert-owned.\ncreate or replace function public.client_update_timings(bid uuid, new_timings text)\nreturns void\nlanguage plpgsql security definer set search_path = public\nas $$\nbegin\n  if not public.owns_business(bid) then\n    raise exception 'not allowed';\n  end if;\n  update brand_profiles set timings = new_timings, updated_at = now() where business_id = bid;\nend;\n$$;\n\ncreate or replace function public.client_update_offering_price(oid uuid, new_price numeric)\nreturns void\nlanguage plpgsql security definer set search_path = public\nas $$\ndeclare bid uuid;\nbegin\n  select business_id into bid from offerings where id = oid;\n  if bid is null or not public.owns_business(bid) then\n    raise exception 'not allowed';\n  end if;\n  update offerings set price = new_price where id = oid;\nend;\n$$;\n\n-- updated_at bookkeeping\ncreate or replace function public.touch_updated_at()\nreturns trigger language plpgsql as $$\nbegin\n  new.updated_at := now();\n  return new;\nend;\n$$;\n\ncreate trigger requests_touch before update on public.requests\n  for each row execute function public.touch_updated_at();\ncreate trigger brand_profiles_touch before update on public.brand_profiles\n  for each row execute function public.touch_updated_at();\ncreate trigger subscriptions_touch before update on public.subscriptions\n  for each row execute function public.touch_updated_at();\ncreate trigger weekly_plans_touch before update on public.weekly_plans\n  for each row execute function public.touch_updated_at();\n" },
  { file: "supabase/migrations/0002_rls.sql", sql: "-- Row Level Security.\n-- Clients: read their own business's data. Their writes (new requests, chat messages,\n-- choosing an option, asking for changes) go through server actions that verify\n-- ownership and then write with the service role, so clients get almost no direct\n-- write policies. Experts: full access.\n\nalter table public.roles              enable row level security;\nalter table public.profiles           enable row level security;\nalter table public.businesses         enable row level security;\nalter table public.brand_profiles     enable row level security;\nalter table public.offerings          enable row level security;\nalter table public.brand_photos       enable row level security;\nalter table public.weekly_plans       enable row level security;\nalter table public.plan_slots         enable row level security;\nalter table public.conversations      enable row level security;\nalter table public.requests           enable row level security;\nalter table public.messages           enable row level security;\nalter table public.conversation_reads enable row level security;\nalter table public.revisions          enable row level security;\nalter table public.content_options    enable row level security;\nalter table public.downloads          enable row level security;\nalter table public.rules              enable row level security;\nalter table public.examples           enable row level security;\nalter table public.festivals          enable row level security;\nalter table public.suggestions        enable row level security;\nalter table public.plans              enable row level security;\nalter table public.subscriptions      enable row level security;\nalter table public.settings           enable row level security;\nalter table public.quick_start_cards  enable row level security;\n\n-- Reference data: readable by any signed-in user, writable by experts\ncreate policy roles_read on public.roles for select to authenticated using (true);\n\ncreate policy festivals_read on public.festivals for select to authenticated using (true);\ncreate policy festivals_write on public.festivals for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy plans_read on public.plans for select to authenticated using (true);\ncreate policy plans_write on public.plans for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy settings_read on public.settings for select to authenticated using (true);\ncreate policy settings_write on public.settings for update to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy qs_read on public.quick_start_cards for select to authenticated using (true);\ncreate policy qs_write on public.quick_start_cards for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\n-- Profiles: users see themselves; experts see everyone.\n-- Only these columns can be changed through the API; the role cannot.\ncreate policy profiles_read on public.profiles for select to authenticated\n  using (id = auth.uid() or public.is_expert());\ncreate policy profiles_update on public.profiles for update to authenticated\n  using (id = auth.uid() or public.is_expert())\n  with check (id = auth.uid() or public.is_expert());\nrevoke update on public.profiles from authenticated;\ngrant update (display_name, preferred_ui_language) on public.profiles to authenticated;\n\n-- Business-scoped tables: owner reads, expert does everything\ncreate policy businesses_read on public.businesses for select to authenticated\n  using (public.can_see_business(id));\ncreate policy businesses_write on public.businesses for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy brand_read on public.brand_profiles for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy brand_write on public.brand_profiles for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy offerings_read on public.offerings for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy offerings_write on public.offerings for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy brand_photos_read on public.brand_photos for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy brand_photos_insert on public.brand_photos for insert to authenticated\n  with check (public.can_see_business(business_id));\ncreate policy brand_photos_delete on public.brand_photos for delete to authenticated\n  using (public.is_expert());\n\ncreate policy weekly_plans_read on public.weekly_plans for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy weekly_plans_write on public.weekly_plans for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy plan_slots_read on public.plan_slots for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy plan_slots_write on public.plan_slots for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy conversations_read on public.conversations for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy conversations_write on public.conversations for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy requests_read on public.requests for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy requests_write on public.requests for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy messages_read on public.messages for select to authenticated\n  using (exists (\n    select 1 from public.conversations c\n    where c.id = conversation_id and public.can_see_business(c.business_id)\n  ));\ncreate policy messages_write on public.messages for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy reads_own on public.conversation_reads for all to authenticated\n  using (profile_id = auth.uid()) with check (profile_id = auth.uid());\ncreate policy reads_expert on public.conversation_reads for select to authenticated\n  using (public.is_expert());\n\ncreate policy revisions_read on public.revisions for select to authenticated\n  using (exists (\n    select 1 from public.requests r where r.id = request_id and public.can_see_business(r.business_id)\n  ));\ncreate policy revisions_write on public.revisions for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\n-- Clients only ever see options that have been delivered, never drafts\ncreate policy options_read_client on public.content_options for select to authenticated\n  using (\n    delivered_at is not null and exists (\n      select 1 from public.requests r where r.id = request_id and public.owns_business(r.business_id)\n    )\n  );\ncreate policy options_expert on public.content_options for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy downloads_read on public.downloads for select to authenticated\n  using (profile_id = auth.uid() or public.is_expert());\n\ncreate policy rules_expert on public.rules for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy examples_expert on public.examples for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy suggestions_read on public.suggestions for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy suggestions_write on public.suggestions for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ncreate policy subscriptions_read on public.subscriptions for select to authenticated\n  using (public.can_see_business(business_id));\ncreate policy subscriptions_write on public.subscriptions for all to authenticated\n  using (public.is_expert()) with check (public.is_expert());\n\ngrant execute on function public.request_access(uuid, public.content_type) to authenticated;\ngrant execute on function public.client_update_timings(uuid, text) to authenticated;\ngrant execute on function public.client_update_offering_price(uuid, numeric) to authenticated;\n\n-- Realtime: chat and queue update live\nalter publication supabase_realtime add table public.messages;\nalter publication supabase_realtime add table public.requests;\n" },
  { file: "supabase/migrations/0003_storage.sql", sql: "-- Private storage buckets. Every object path starts with the business id:\n--   <business_id>/<...>\n-- Clients can read their own business's files; experts can read and write everything.\n\ninsert into storage.buckets (id, name, public, file_size_limit)\nvalues\n  ('client-uploads', 'client-uploads', false, 10485760),   -- 10 MB (photos are compressed first)\n  ('voice-notes',    'voice-notes',    false, 10485760),\n  ('deliverables',   'deliverables',   false, 52428800),   -- 50 MB (video cap)\n  ('brand-assets',   'brand-assets',   false, 10485760),\n  ('examples',       'examples',       false, 52428800)\non conflict (id) do nothing;\n\n-- Read\ncreate policy sg_read_own on storage.objects for select to authenticated\n  using (\n    bucket_id in ('client-uploads', 'voice-notes', 'deliverables', 'brand-assets')\n    and public.owns_business_folder((storage.foldername(name))[1])\n  );\ncreate policy sg_read_expert on storage.objects for select to authenticated\n  using (\n    bucket_id in ('client-uploads', 'voice-notes', 'deliverables', 'brand-assets', 'examples')\n    and public.is_expert()\n  );\n\n-- Clients upload photos and voice notes into their own folder\ncreate policy sg_client_upload on storage.objects for insert to authenticated\n  with check (\n    bucket_id in ('client-uploads', 'voice-notes')\n    and public.owns_business_folder((storage.foldername(name))[1])\n  );\n\n-- Experts write anywhere\ncreate policy sg_expert_insert on storage.objects for insert to authenticated\n  with check (\n    bucket_id in ('client-uploads', 'voice-notes', 'deliverables', 'brand-assets', 'examples')\n    and public.is_expert()\n  );\ncreate policy sg_expert_update on storage.objects for update to authenticated\n  using (public.is_expert() and bucket_id in ('deliverables', 'brand-assets', 'examples'));\ncreate policy sg_expert_delete on storage.objects for delete to authenticated\n  using (public.is_expert() and bucket_id in ('deliverables', 'brand-assets', 'examples'));\n" },
  { file: "supabase/migrations/0004_post_credits.sql", sql: "-- Pay-per-post: each verified ₹ per-post payment adds one credit; asking for a post without\n-- an active plan uses one up. Safe to run more than once.\nalter table public.subscriptions\n  add column if not exists post_credits int not null default 0 check (post_credits >= 0);\n" },
  { file: "supabase/seed.sql", sql: "-- Reference data: placeholder plan, festival calendar (Oct 2026 – Oct 2027), quick-start cards.\n-- Users and sample clients are created by `npm run seed` (scripts/seed.ts), which needs the\n-- Supabase Auth admin API.\n--\n-- Lunar-calendar festival dates below are best estimates. Check them once in\n-- Expert → Settings → Festival calendar before relying on them.\n\ninsert into public.plans (name, price_inr, limits)\nselect 'Pilot', 0, '{\"requests_per_month\": null, \"content_types\": null}'\nwhere not exists (select 1 from public.plans where name = 'Pilot');\n\ninsert into public.festivals (name, name_hi, date, industries, default_lead_days) values\n  ('World Food Day',            'विश्व खाद्य दिवस',        '2026-10-16', '{restaurant,cafe,cloud_kitchen}', 5),\n  ('Durga Puja',                'दुर्गा पूजा',              '2026-10-17', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Dussehra',                  'दशहरा',                   '2026-10-20', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Karva Chauth',              'करवा चौथ',                '2026-10-29', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Dhanteras',                 'धनतेरस',                  '2026-11-06', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Diwali',                    'दिवाली',                  '2026-11-08', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Bhai Dooj',                 'भाई दूज',                 '2026-11-11', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Children''s Day',           'बाल दिवस',                '2026-11-14', '{restaurant,cafe,cloud_kitchen}', 5),\n  ('Chhath Puja',               'छठ पूजा',                 '2026-11-15', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Wedding season',            'शादी का सीज़न',            '2026-11-21', '{salon,restaurant,cafe,cloud_kitchen}', 10),\n  ('Guru Nanak Jayanti',        'गुरु नानक जयंती',          '2026-11-24', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Christmas',                 'क्रिसमस',                 '2026-12-25', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('New Year''s Eve',           'नए साल की शाम',            '2026-12-31', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('New Year',                  'नया साल',                 '2027-01-01', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Lohri',                     'लोहड़ी',                   '2027-01-13', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Makar Sankranti / Pongal',  'मकर संक्रांति / पोंगल',      '2027-01-14', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Republic Day',              'गणतंत्र दिवस',             '2027-01-26', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Vasant Panchami',           'वसंत पंचमी',               '2027-02-11', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Valentine''s Day',          'वैलेंटाइन डे',             '2027-02-14', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Maha Shivratri',            'महा शिवरात्रि',            '2027-03-06', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Women''s Day',              'महिला दिवस',               '2027-03-08', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Eid ul-Fitr',               'ईद उल-फ़ित्र',              '2027-03-10', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Holi',                      'होली',                    '2027-03-22', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Chaitra Navratri / Gudi Padwa', 'चैत्र नवरात्रि / गुड़ी पड़वा', '2027-04-07', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Baisakhi',                  'बैसाखी',                  '2027-04-14', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Ram Navami',                'राम नवमी',                '2027-04-15', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Mother''s Day',             'मदर्स डे',                '2027-05-09', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Eid al-Adha',               'ईद उल-अज़हा',              '2027-05-17', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Father''s Day',             'फादर्स डे',               '2027-06-20', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Monsoon season',            'मानसून',                  '2027-07-01', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Friendship Day',            'फ्रेंडशिप डे',             '2027-08-01', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Independence Day',          'स्वतंत्रता दिवस',           '2027-08-15', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Raksha Bandhan',            'रक्षा बंधन',               '2027-08-17', '{salon,restaurant,cafe,cloud_kitchen}', 7),\n  ('Janmashtami',               'जन्माष्टमी',               '2027-08-25', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Ganesh Chaturthi',          'गणेश चतुर्थी',             '2027-09-04', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Onam',                      'ओणम',                    '2027-09-12', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Navratri',                  'नवरात्रि',                 '2027-09-30', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('Dussehra',                  'दशहरा',                   '2027-10-09', '{salon,restaurant,cafe,cloud_kitchen}', 5),\n  ('World Food Day',            'विश्व खाद्य दिवस',        '2027-10-16', '{restaurant,cafe,cloud_kitchen}', 5)\non conflict do nothing;\n\n-- Quick-start cards. Food businesses (restaurant, cafe, cloud kitchen) share one set.\ndo $$\ndeclare\n  ind public.industry;\nbegin\n  foreach ind in array array['restaurant', 'cafe', 'cloud_kitchen']::public.industry[] loop\n    insert into public.quick_start_cards (industry, key, label_en, label_hi, icon, content_type, sort, questions) values\n    (ind, 'todays_special', 'Today''s special', 'आज का स्पेशल', 'chef-hat', 'single_post', 1,\n     '[{\"id\":\"item\",\"type\":\"text\",\"q_en\":\"Which dish is today''s special?\",\"q_hi\":\"आज का स्पेशल कौन सा पकवान है?\"},\n       {\"id\":\"price\",\"type\":\"choice\",\"q_en\":\"Show the price on the post?\",\"q_hi\":\"पोस्ट पर दाम दिखाएँ?\",\"options\":[{\"en\":\"Yes, show price\",\"hi\":\"हाँ, दाम दिखाएँ\"},{\"en\":\"No price\",\"hi\":\"दाम नहीं\"}]},\n       {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Add a photo of the dish\",\"q_hi\":\"पकवान की फ़ोटो जोड़ें\"}]'),\n    (ind, 'new_offer', 'New offer', 'नया ऑफ़र', 'tag', 'single_post', 2,\n     '[{\"id\":\"offer\",\"type\":\"choice\",\"q_en\":\"What kind of offer?\",\"q_hi\":\"कैसा ऑफ़र है?\",\"options\":[{\"en\":\"% discount\",\"hi\":\"% छूट\"},{\"en\":\"Buy 1 Get 1\",\"hi\":\"एक के साथ एक फ्री\"},{\"en\":\"Combo deal\",\"hi\":\"कॉम्बो डील\"},{\"en\":\"Free item\",\"hi\":\"फ्री आइटम\"}],\"allow_text\":true},\n       {\"id\":\"until\",\"type\":\"choice\",\"q_en\":\"Till when?\",\"q_hi\":\"कब तक?\",\"options\":[{\"en\":\"Today only\",\"hi\":\"सिर्फ़ आज\"},{\"en\":\"This week\",\"hi\":\"इस हफ़्ते\"},{\"en\":\"This month\",\"hi\":\"इस महीने\"}]},\n       {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Any photo to use?\",\"q_hi\":\"कोई फ़ोटो लगानी है?\"}]'),\n    (ind, 'festival_post', 'Festival post', 'त्योहार पोस्ट', 'party-popper', 'festival_greeting', 3,\n     '[{\"id\":\"festival\",\"type\":\"text\",\"q_en\":\"Which festival?\",\"q_hi\":\"कौन सा त्योहार?\"},\n       {\"id\":\"offer\",\"type\":\"choice\",\"q_en\":\"Add a festival offer?\",\"q_hi\":\"त्योहार का ऑफ़र जोड़ें?\",\"options\":[{\"en\":\"Yes, add offer\",\"hi\":\"हाँ, ऑफ़र जोड़ें\"},{\"en\":\"Only greetings\",\"hi\":\"सिर्फ़ शुभकामनाएँ\"}],\"allow_text\":true}]'),\n    (ind, 'menu_spotlight', 'Menu item spotlight', 'मेन्यू आइटम ख़ास', 'utensils', 'single_post', 4,\n     '[{\"id\":\"item\",\"type\":\"text\",\"q_en\":\"Which menu item?\",\"q_hi\":\"कौन सा मेन्यू आइटम?\"},\n       {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Add a photo of it\",\"q_hi\":\"उसकी फ़ोटो जोड़ें\"}]'),\n    (ind, 'customer_review', 'Customer review post', 'ग्राहक रिव्यू पोस्ट', 'star', 'single_post', 5,\n     '[{\"id\":\"review\",\"type\":\"text\",\"q_en\":\"Type or paste the review\",\"q_hi\":\"रिव्यू लिखें या पेस्ट करें\"},\n       {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Screenshot or photo (optional)\",\"q_hi\":\"स्क्रीनशॉट या फ़ोटो (अगर हो)\"}]'),\n    (ind, 'reel_idea', 'Reel idea', 'रील आइडिया', 'clapperboard', 'reel', 6,\n     '[{\"id\":\"topic\",\"type\":\"choice\",\"q_en\":\"What should the reel show?\",\"q_hi\":\"रील में क्या दिखाना है?\",\"options\":[{\"en\":\"Food being made\",\"hi\":\"खाना बनते हुए\"},{\"en\":\"Behind the scenes\",\"hi\":\"किचन के पीछे की झलक\"},{\"en\":\"Happy customers\",\"hi\":\"खुश ग्राहक\"},{\"en\":\"New dish\",\"hi\":\"नया पकवान\"}],\"allow_text\":true}]')\n    on conflict (industry, key) do nothing;\n  end loop;\n\n  insert into public.quick_start_cards (industry, key, label_en, label_hi, icon, content_type, sort, questions) values\n  ('salon', 'new_offer', 'New offer', 'नया ऑफ़र', 'tag', 'single_post', 1,\n   '[{\"id\":\"service\",\"type\":\"text\",\"q_en\":\"Offer on which service?\",\"q_hi\":\"किस सर्विस पर ऑफ़र है?\"},\n     {\"id\":\"offer\",\"type\":\"choice\",\"q_en\":\"What kind of offer?\",\"q_hi\":\"कैसा ऑफ़र है?\",\"options\":[{\"en\":\"% discount\",\"hi\":\"% छूट\"},{\"en\":\"Package deal\",\"hi\":\"पैकेज डील\"},{\"en\":\"Free add-on\",\"hi\":\"फ्री ऐड-ऑन\"}],\"allow_text\":true},\n     {\"id\":\"until\",\"type\":\"choice\",\"q_en\":\"Till when?\",\"q_hi\":\"कब तक?\",\"options\":[{\"en\":\"Today only\",\"hi\":\"सिर्फ़ आज\"},{\"en\":\"This week\",\"hi\":\"इस हफ़्ते\"},{\"en\":\"This month\",\"hi\":\"इस महीने\"}]}]'),\n  ('salon', 'before_after', 'Before & after', 'पहले और बाद', 'sparkles', 'carousel', 2,\n   '[{\"id\":\"service\",\"type\":\"text\",\"q_en\":\"Which service was done?\",\"q_hi\":\"कौन सी सर्विस की गई?\"},\n     {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Add the before and after photos\",\"q_hi\":\"पहले और बाद की फ़ोटो जोड़ें\"}]'),\n  ('salon', 'festival_post', 'Festival post', 'त्योहार पोस्ट', 'party-popper', 'festival_greeting', 3,\n   '[{\"id\":\"festival\",\"type\":\"text\",\"q_en\":\"Which festival?\",\"q_hi\":\"कौन सा त्योहार?\"},\n     {\"id\":\"offer\",\"type\":\"choice\",\"q_en\":\"Add a festival offer?\",\"q_hi\":\"त्योहार का ऑफ़र जोड़ें?\",\"options\":[{\"en\":\"Yes, add offer\",\"hi\":\"हाँ, ऑफ़र जोड़ें\"},{\"en\":\"Only greetings\",\"hi\":\"सिर्फ़ शुभकामनाएँ\"}],\"allow_text\":true}]'),\n  ('salon', 'new_service', 'New service', 'नई सर्विस', 'scissors', 'single_post', 4,\n   '[{\"id\":\"service\",\"type\":\"text\",\"q_en\":\"What is the new service?\",\"q_hi\":\"नई सर्विस क्या है?\"},\n     {\"id\":\"price\",\"type\":\"choice\",\"q_en\":\"Show the price on the post?\",\"q_hi\":\"पोस्ट पर दाम दिखाएँ?\",\"options\":[{\"en\":\"Yes, show price\",\"hi\":\"हाँ, दाम दिखाएँ\"},{\"en\":\"No price\",\"hi\":\"दाम नहीं\"}]},\n     {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Any photo to use?\",\"q_hi\":\"कोई फ़ोटो लगानी है?\"}]'),\n  ('salon', 'customer_review', 'Customer review post', 'ग्राहक रिव्यू पोस्ट', 'star', 'single_post', 5,\n   '[{\"id\":\"review\",\"type\":\"text\",\"q_en\":\"Type or paste the review\",\"q_hi\":\"रिव्यू लिखें या पेस्ट करें\"},\n     {\"id\":\"photo\",\"type\":\"photo\",\"q_en\":\"Screenshot or photo (optional)\",\"q_hi\":\"स्क्रीनशॉट या फ़ोटो (अगर हो)\"}]'),\n  ('salon', 'reel_idea', 'Reel idea', 'रील आइडिया', 'clapperboard', 'reel', 6,\n   '[{\"id\":\"topic\",\"type\":\"choice\",\"q_en\":\"What should the reel show?\",\"q_hi\":\"रील में क्या दिखाना है?\",\"options\":[{\"en\":\"A makeover\",\"hi\":\"मेकओवर\"},{\"en\":\"Hair styling\",\"hi\":\"हेयर स्टाइलिंग\"},{\"en\":\"Salon tour\",\"hi\":\"सैलून की झलक\"},{\"en\":\"Happy customers\",\"hi\":\"खुश ग्राहक\"}],\"allow_text\":true}]')\n  on conflict (industry, key) do nothing;\nend $$;\n" },
];
